# owner: platform
"""Lay students out in rows of seats."""

from rosterkit.models import Student


def _sort_key(pupil: Student):
    last = pupil.last_name.lower()
    return (last, pupil.first_name.lower())


def _format_row(number, group):
    names = [pupil.display_name for pupil in group]
    return f"Row {number}: " + " | ".join(names)


def _check(students, seats):
    if seats <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")


# ---
def seating_rows(students, seats):
    """Sort by last name, return one text line per row."""
    _check(students, seats)
    ordered = sorted(students, key=_sort_key)
    rows = range(0, len(ordered), seats)
    return [_format_row(start // seats + 1,
                        ordered[start:start + seats])
            for start in rows]

