# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def make(last, first):
    return Student(last + first, last, first, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.pupils = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Abbot", "Cleo")
        ]

    def test_sorted_rows_of_two(self):
        want = [
            "Row 1: Abbot, Cleo | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ]
        found = seating_rows(self.pupils, 2)
        self.assertEqual(found, want)

    def test_single_long_row(self):
        lines = seating_rows(self.pupils, 10)
        self.assertEqual(len(lines), 1)

    def test_sort_ignores_case(self):
        mixed = [make("zed", "A"), make("Young", "B")]
        self.assertEqual(
            seating_rows(mixed, 1),
            ["Row 1: Young, B", "Row 2: zed, A"])

    def test_first_name_breaks_ties(self):
        pair = [make("Lee", "Zoe"), make("Lee", "Amy")]
        self.assertEqual(
            seating_rows(pair, 2),
            ["Row 1: Lee, Amy | Lee, Zoe"])

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.pupils, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.pupils, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
